/**
 * Social → Analytics → Digests: every stored digest (scheduled or generated by
 * hand), newest first — open one, email it again, delete it, or generate a new
 * one for a chosen period.
 */
import type { SocialAnalyticsDigestSummary, } from '@sitesurge/types';
import { A, useNavigate, } from '@solidjs/router';
import { type Component, createEffect, createResource, createSignal, For, onCleanup, Show, } from 'solid-js';
import AdminTitle from '../../../../components/admin/common/AdminTitle';
import ConfirmModal from '../../../../components/admin/common/ConfirmModal';
import ModalShell from '../../../../components/admin/common/ModalShell';
import Pagination from '../../../../components/admin/common/Pagination';
import Toggle from '../../../../components/admin/common/Toggle';
import { CommitInput, FormField, } from '../../../../components/admin/forms';
import { StableSuspense, } from '../../../../components/common/StableSuspense';
import { useToast, } from '../../../../components/common/toast';
import { cms, } from '../../../../services/cmsClient';
import AnalyticsNav from './AnalyticsNav';
import { daysAgo, periodLabel, } from './digestFormat';

const LIMIT = 20;

const when = (iso: string | null,) => (iso ? new Date(iso,).toLocaleString() : '—');

export const StatusBadge: Component<{ status: SocialAnalyticsDigestSummary['status']; }> = (p,) => (
    <span class={`digest-status digest-status--${p.status}`}>
        {p.status === 'ready' ? 'Ready' : p.status === 'failed' ? 'Failed' : 'Generating…'}
    </span>
);

type Preset = '7' | '30' | 'custom';

const GenerateModal: Component<{ onClose: () => void; onDone: (id: string,) => void; }> = (props,) => {
    const toast = useToast();
    const [preset, setPreset,] = createSignal<Preset>('7',);
    const [from, setFrom,] = createSignal(daysAgo(7,),);
    const [to, setTo,] = createSignal(daysAgo(1,),);
    const [email, setEmail,] = createSignal(false,);
    const [busy, setBusy,] = createSignal(false,);
    const [error, setError,] = createSignal('',);

    const range = () => {
        if (preset() === '7') return { from: daysAgo(7,), to: daysAgo(1,), };
        if (preset() === '30') return { from: daysAgo(30,), to: daysAgo(1,), };
        return { from: from(), to: to(), };
    };

    const run = async () => {
        const r = range();
        if (!/^\d{4}-\d{2}-\d{2}$/.test(r.from,) || !/^\d{4}-\d{2}-\d{2}$/.test(r.to,) || r.from > r.to) {
            setError('Choose a valid period (from ≤ to).',);
            return;
        }
        setBusy(true,);
        setError('',);
        try {
            // Returns at once ('generating'); the digest page polls until it is ready.
            const d = await cms.socialAnalytics.generateDigest({ ...r, email: email(), },);
            toast.info('Generating the digest…',);
            props.onDone(d.id,);
        } catch (e) {
            setError(e instanceof Error ? e.message : 'Could not generate the digest.',);
        } finally {
            setBusy(false,);
        }
    };

    return (
        <ModalShell open onClose={props.onClose} size="sm" showClose ariaLabel="Generate a digest">
            <div class="digests-generate">
                <h2 class="digests-generate__title">Generate a digest</h2>
                <FormField label="Period">
                    <select value={preset()} onChange={(e,) => setPreset(e.currentTarget.value as Preset,)}>
                        <option value="7">Last 7 days</option>
                        <option value="30">Last 30 days</option>
                        <option value="custom">Custom…</option>
                    </select>
                </FormField>
                <Show when={preset() === 'custom'}>
                    <div class="admin-form-row">
                        <FormField label="From"><CommitInput type="date" value={from()} onCommit={setFrom} /></FormField>
                        <FormField label="To"><CommitInput type="date" value={to()} onCommit={setTo} /></FormField>
                    </div>
                </Show>
                <p class="form-help-muted">{periodLabel(range().from, range().to,)} · compared with the period just before it.</p>
                <Toggle checked={email()} onChange={setEmail} label="Also email it to the digest recipients" />
                <Show when={error()}><div class="alert alert--error">{error()}</div></Show>
                <div class="form-actions">
                    <button type="button" class="ui-button ui-button--secondary" onClick={props.onClose} disabled={busy()}>Cancel</button>
                    <button type="button" class="ui-button ui-button--primary" onClick={run} disabled={busy()}>
                        {busy() ? 'Starting…' : 'Generate'}
                    </button>
                </div>
            </div>
        </ModalShell>
    );
};

const DigestsPage: Component = () => {
    const toast = useToast();
    const navigate = useNavigate();
    const [page, setPage,] = createSignal(1,);
    const [list, { refetch, },] = createResource(page, (p,) => cms.socialAnalytics.digests({ page: p, limit: LIMIT, },),);
    const [settings,] = createResource(() => cms.socialAnalytics.settings().catch(() => null),);
    // Rows still 'generating' (e.g. a scheduled digest being written): re-read every 5 s.
    let poll: ReturnType<typeof setTimeout> | undefined;
    createEffect(() => {
        const l = list();
        clearTimeout(poll,);
        if (l && l.data.some((d,) => d.status === 'generating')) poll = setTimeout(() => refetch(), 5000,);
    },);
    onCleanup(() => clearTimeout(poll,),);
    const [generating, setGenerating,] = createSignal(false,);
    const [toDelete, setToDelete,] = createSignal<SocialAnalyticsDigestSummary | null>(null,);
    const [deleting, setDeleting,] = createSignal(false,);
    const [sendingId, setSendingId,] = createSignal<string | null>(null,);

    const send = async (d: SocialAnalyticsDigestSummary,) => {
        setSendingId(d.id,);
        try {
            const r = await cms.socialAnalytics.sendDigest(d.id,);
            toast.success(r.sent ? `Emailed to ${r.sent} recipient${r.sent === 1 ? '' : 's'}` : 'No recipients — add them in Settings',);
            refetch();
        } catch (e) {
            toast.error(`Could not email it: ${(e as Error).message}`,);
        } finally {
            setSendingId(null,);
        }
    };

    const remove = async () => {
        const d = toDelete();
        if (!d) return;
        setDeleting(true,);
        try {
            await cms.socialAnalytics.deleteDigest(d.id,);
            toast.success('Digest deleted',);
            setToDelete(null,);
            refetch();
        } catch (e) {
            toast.error(`Could not delete it: ${(e as Error).message}`,);
        } finally {
            setDeleting(false,);
        }
    };

    return (
        <section class="digests-page">
            <AdminTitle>Analytics Digests</AdminTitle>
            <AnalyticsNav
                actions={
                    <button type="button" class="ui-button ui-button--primary ui-button--sm" onClick={() => setGenerating(true,)}>
                        Generate now
                    </button>
                }
            />

            <Show when={settings()}>
                {(s,) => (
                    <p class="form-help-muted digests-page__schedule">
                        {s().digest.enabled
                            ? <>Scheduled digests are on ({s().digest.frequency}). </>
                            : <>Scheduled digests are off. </>}
                        <A href="/admin/social/analytics/settings">Change in Settings →</A>
                    </p>
                )}
            </Show>

            <StableSuspense fallback={<p class="form-help-muted">Loading…</p>}>
                <Show when={list()} fallback={<Show when={list.error}><div class="alert alert--error">{(list.error as Error)?.message}</div></Show>}>
                    {(l,) => (
                        <Show
                            when={l().data.length}
                            fallback={
                                <div class="empty-state digests-page__empty">
                                    <h3>No digests yet</h3>
                                    <p>
                                        A digest is a report of your social analytics for a period — totals, per-platform numbers, trends, top
                                        posts and AI insights — kept here and optionally emailed.
                                    </p>
                                    <p>
                                        Turn on the schedule in <A href="/admin/social/analytics/settings">Settings</A>, or press{' '}
                                        <strong>Generate now</strong> for one right away.
                                    </p>
                                </div>
                            }
                        >
                            <div class="digests-page__table-wrap">
                                <table class="admin-table digests-table">
                                    <thead>
                                        <tr>
                                            <th>Period</th>
                                            <th>Type</th>
                                            <th>Status</th>
                                            <th>Headline</th>
                                            <th>Emailed</th>
                                            <th />
                                        </tr>
                                    </thead>
                                    <tbody>
                                        <For each={l().data}>
                                            {(d,) => (
                                                <tr>
                                                    <td class="digests-table__period">
                                                        <A href={`/admin/social/analytics/digests/${d.id}`}>{periodLabel(d.from, d.to,)}</A>
                                                        <div class="form-help-muted">{when(d.createdAt,)}</div>
                                                    </td>
                                                    <td>{d.trigger === 'schedule' ? `Scheduled · ${d.frequency}` : 'By hand'}</td>
                                                    <td>
                                                        <StatusBadge status={d.status} />
                                                        <Show when={d.error}><div class="form-help-muted digests-table__error" title={d.error!}>{d.error}</div></Show>
                                                    </td>
                                                    <td class="digests-table__headline">{d.headline || <span class="form-help-muted">—</span>}</td>
                                                    <td>
                                                        <Show when={d.emailedAt} fallback={<span class="form-help-muted">—</span>}>
                                                            {d.emailCount} · <span class="form-help-muted">{when(d.emailedAt,)}</span>
                                                        </Show>
                                                    </td>
                                                    <td class="digests-table__actions">
                                                        <A class="ui-button ui-button--secondary ui-button--sm" href={`/admin/social/analytics/digests/${d.id}`}>View</A>
                                                        <button type="button" class="ui-button ui-button--secondary ui-button--sm" disabled={d.status !== 'ready' || sendingId() === d.id} onClick={() => send(d,)}>
                                                            {sendingId() === d.id ? 'Sending…' : 'Email again'}
                                                        </button>
                                                        <button type="button" class="ui-button ui-button--danger ui-button--sm" onClick={() => setToDelete(d,)}>Delete</button>
                                                    </td>
                                                </tr>
                                            )}
                                        </For>
                                    </tbody>
                                </table>
                            </div>
                            <Pagination
                                page={page()}
                                totalPages={l().meta.totalPages ?? 1}
                                total={l().meta.total}
                                limit={LIMIT}
                                onPageChange={setPage}
                            />
                        </Show>
                    )}
                </Show>
            </StableSuspense>

            <Show when={generating()}>
                <GenerateModal
                    onClose={() => setGenerating(false,)}
                    onDone={(id,) => {
                        setGenerating(false,);
                        navigate(`/admin/social/analytics/digests/${id}`,);
                    }}
                />
            </Show>

            <ConfirmModal
                open={Boolean(toDelete(),)}
                title="Delete this digest?"
                message={toDelete() ? `The digest for ${periodLabel(toDelete()!.from, toDelete()!.to,)} and its data snapshot are deleted. The analytics data itself is kept.` : ''}
                confirmLabel="Delete"
                busyLabel="Deleting…"
                loading={deleting()}
                danger
                onConfirm={remove}
                onCancel={() => setToDelete(null,)}
            />
        </section>
    );
};

export default DigestsPage;
